<?phpif (!defined('OK_LOADED')) exit;// ---------------------------------------------------------// ვიზიტების ტაბის დამატება (Hook სისტემით)// ---------------------------------------------------------if (function_exists('add_ok_action')) {        add_ok_action('init_profile_tabs', function() {                // ვამოწმებთ, რომ პროფილის სისტემა მზად არის მიიღოს ტაბი        if (function_exists('add_ok_profile_tab')) {                        add_ok_profile_tab(                'appointments',       // Slug (უნიკალური ID)                'ვიზიტები',           // სათაური                'bi-calendar-check',  // აიკონი                function($user) {     // ფუნქცია, რომელიც ხატავს კონტენტს                                        // შორთკოდის გამოძახება                    // ვამოწმებთ რომელი ფუნქციაა ხელმისაწვდომი სისტემაში                    if (function_exists('ok_do_shortcode')) {                        echo ok_do_shortcode('[ok_main_cabinet]');                    } elseif (function_exists('do_shortcode')) {                        echo do_shortcode('[ok_main_cabinet]');                    } else {                        // თუ არცერთი ფუნქცია არ არის, უბრალოდ ტექსტს ვბეჭდავთ                        echo do_ok_shortcode('[ok_main_cabinet]');                     }                },                10 // რიგითობა (რაც დაბალია, მით უფრო ზემოთ გამოჩნდება)            );        }    });}?>